/// The kinds of parameter the engine compiles, named as UnCiv's signatures name them.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum ParamKind {
    /// `amount`: a whole number.
    Amount,
    /// `amount16`: a whole number stored in 16 bits.
    Amount16,
    /// `relativeAmount`: a change in percent: `+15`, `-33`.
    RelativeAmount,
    /// `positiveAmount`: a whole number, at least 1.
    PositiveAmount,
    /// `nonNegativeAmount`: a whole number, at least 0.
    NonNegativeAmount,
    /// `fraction`: a real number, interned in `Ruleset::fracs`.
    Fraction,
    /// `stats`: stats such as `+1 Food, +2 Gold`, interned.
    Stats,
    /// `stat`: one stat: `Gold`.
    Stat,
    /// `civWideStat`: a stat pooled per civilization.
    CivWideStat,
    /// `stockpile`: a stat a civilization stockpiles.
    Stockpile,
    /// `stat/resource`: a stat or a resource.
    StatOrResource,
    /// `cityFilter`: a city filter.
    CityFilter,
    /// `mapUnitFilter`: a filter on units on the map.
    MapUnitFilter,
    /// `civFilter`: a civilization filter.
    CivFilter,
    /// `combatantFilter`: a combatant filter.
    CombatantFilter,
    /// `tileFilter`: a tile filter.
    TileFilter,
    /// `terrainFilter`: a filter on a tile's terrain.
    TerrainFilter,
    /// `simpleTerrain`: a terrain, `Land`, `Water` or `Elevated`.
    SimpleTerrain,
    /// `baseUnitFilter`: a filter on the units of units.json.
    BaseUnitFilter,
    /// `buildingFilter`: a building filter.
    BuildingFilter,
    /// `improvementFilter`: an improvement filter.
    ImprovementFilter,
    /// `resourceFilter`: a resource filter.
    ResourceFilter,
    /// `techFilter`: a technology filter.
    TechFilter,
    /// `eraFilter`: an era filter.
    EraFilter,
    /// `tileFilter/buildingFilter`: a tile or building filter.
    TileOrBuildingFilter,
    /// `tileFilter/specialist/buildingFilter`: a tile filter, a specialist or a building filter.
    TileSpecialistOrBuildingFilter,
    /// `improvementFilter/terrainFilter`: an improvement or terrain filter.
    ImprovementOrTerrainFilter,
    /// `buildingName`: a building, by name.
    BuildingName,
    /// `unit`: a unit of units.json, by name.
    Unit,
    /// `greatPerson`: a great person's unit, by name.
    GreatPerson,
    /// `promotion`: a promotion, by name.
    Promotion,
    /// `resource`: a resource, by name.
    Resource,
    /// `tech`: a technology, by name.
    Tech,
    /// `era`: an era, by name.
    Era,
    /// `difficulty`: a difficulty, by name.
    Difficulty,
    /// `speed`: a game speed, by name.
    Speed,
    /// `victoryType`: a victory, by name.
    VictoryType,
    /// `terrainName`: a terrain, by name.
    TerrainName,
    /// `terrainFeature`: a terrain feature, by name.
    TerrainFeature,
    /// `baseTerrain/terrainFeature`: a base terrain or a feature, by name.
    BaseTerrainOrFeature,
    /// `policy/belief`: a policy or a belief, by name.
    PolicyOrBelief,
    /// `populationFilter`: which citizens count.
    PopulationFilter,
    /// `costOrStrength`: `Cost` or `Strength`.
    CostOrStrength,
    /// `foundingOrEnhancing`: `founding` or `enhancing`.
    FoundingOrEnhancing,
    /// `beliefType`: a belief type, or `Any`.
    BeliefType,
    /// `spyAction`: what a spy is doing: `Stealing Tech`.
    SpyAction,
    /// `terrainQuality`: how a start values a terrain.
    TerrainQuality,
    /// `regionType`: a kind of start region.
    RegionType,
    /// `unitTriggerTarget`: the unit a one-time effect acts on.
    UnitTriggerTarget,
    /// `countable`: something counted: a number, `Cities`, ....
    Countable,
    /// `positiveAmount/'all'`: a count, or `All`.
    CountOrAll,
    /// `comment`: free text, interned.
    Comment,
    /// `pediaLink`: a Civilopedia link, as text.
    PediaLink,
    /// `validationWarning`: a ruleset checker's warning, as text.
    ValidationWarning,
}

impl ParamKind {
    /// The kind's name in UnCiv's signatures.
    #[must_use]
    pub const fn name(self) -> &'static str {
        match self {
            Self::Amount => "amount",
            Self::Amount16 => "amount16",
            Self::RelativeAmount => "relativeAmount",
            Self::PositiveAmount => "positiveAmount",
            Self::NonNegativeAmount => "nonNegativeAmount",
            Self::Fraction => "fraction",
            Self::Stats => "stats",
            Self::Stat => "stat",
            Self::CivWideStat => "civWideStat",
            Self::Stockpile => "stockpile",
            Self::StatOrResource => "stat/resource",
            Self::CityFilter => "cityFilter",
            Self::MapUnitFilter => "mapUnitFilter",
            Self::CivFilter => "civFilter",
            Self::CombatantFilter => "combatantFilter",
            Self::TileFilter => "tileFilter",
            Self::TerrainFilter => "terrainFilter",
            Self::SimpleTerrain => "simpleTerrain",
            Self::BaseUnitFilter => "baseUnitFilter",
            Self::BuildingFilter => "buildingFilter",
            Self::ImprovementFilter => "improvementFilter",
            Self::ResourceFilter => "resourceFilter",
            Self::TechFilter => "techFilter",
            Self::EraFilter => "eraFilter",
            Self::TileOrBuildingFilter => "tileFilter/buildingFilter",
            Self::TileSpecialistOrBuildingFilter => "tileFilter/specialist/buildingFilter",
            Self::ImprovementOrTerrainFilter => "improvementFilter/terrainFilter",
            Self::BuildingName => "buildingName",
            Self::Unit => "unit",
            Self::GreatPerson => "greatPerson",
            Self::Promotion => "promotion",
            Self::Resource => "resource",
            Self::Tech => "tech",
            Self::Era => "era",
            Self::Difficulty => "difficulty",
            Self::Speed => "speed",
            Self::VictoryType => "victoryType",
            Self::TerrainName => "terrainName",
            Self::TerrainFeature => "terrainFeature",
            Self::BaseTerrainOrFeature => "baseTerrain/terrainFeature",
            Self::PolicyOrBelief => "policy/belief",
            Self::PopulationFilter => "populationFilter",
            Self::CostOrStrength => "costOrStrength",
            Self::FoundingOrEnhancing => "foundingOrEnhancing",
            Self::BeliefType => "beliefType",
            Self::SpyAction => "spyAction",
            Self::TerrainQuality => "terrainQuality",
            Self::RegionType => "regionType",
            Self::UnitTriggerTarget => "unitTriggerTarget",
            Self::Countable => "countable",
            Self::CountOrAll => "positiveAmount/'all'",
            Self::Comment => "comment",
            Self::PediaLink => "pediaLink",
            Self::ValidationWarning => "validationWarning",
        }
    }
}

/// An engine system that reads a unique type: `unique_supported.toml`'s `stages`.
